UPDATE ai_persona_version v
JOIN ai_persona_source s ON s.id = v.persona_source_id
SET v.status = 'published',
    v.published_at = NOW(),
    v.published_by = #{userId}
WHERE v.persona_source_id = #{personaId}
  AND v.version = #{version}
  AND s.owner_user_id = #{userId}
  AND s.archived = 0
  AND v.status != 'archived'
  AND JSON_UNQUOTE(JSON_EXTRACT(v.validation_report, '$.valid')) = 'true'
  AND v.test_status = 'passed'

UPDATE ai_persona_source s
JOIN ai_persona_version v
  ON v.persona_source_id = s.id
 AND v.version = #{version}
 AND v.status = 'published'
SET s.latest_published_version = v.version,
    s.visibility = #{visibility},
    s.updated_at = NOW(),
    s.updater = #{userId}
WHERE s.id = #{personaId}
  AND s.owner_user_id = #{userId}
  AND s.archived = 0

UPDATE ai_persona_version v
JOIN ai_persona_source s ON s.id = v.persona_source_id
SET v.status = 'archived', v.archived_at = NOW()
WHERE v.persona_source_id = #{personaId}
  AND v.version = #{version}
  AND (s.latest_published_version IS NULL OR s.latest_published_version != #{version})

UPDATE ai_persona_test_run
SET status = #{status}, score_json = #{scoreJson}, report_json = #{reportJson}
WHERE id = #{id}

UPDATE ai_persona_version
SET test_status = #{testStatus}, quality_score = #{qualityScore}, test_report = #{testReport}
WHERE persona_source_id = #{personaId} AND version = #{version} AND status != 'archived'

